#!/usr/bin/env python3
"""
OTscope

Interactive Multi-Pcap OT/ICS Traffic Analysis Tool

Purpose:
    Analyze one or more OT/ICS packet capture files as a unified session,
    infer device roles and zones, generate findings, and produce a Word report.

Protocol Coverage:
    Capture Inventory, Modbus TCP, BACnet/IP, DNP3, IEC 61850 / GOOSE / MMS,
    MQTT, OPC-UA, EtherNet/IP / CIP, Siemens S7 / PROFINET, Physical Security,
    cleartext and legacy services, segmentation and intrusion indicators.

Author:
    Ryan Lyford  (original design, implementation, and detection rules)

Copyright:
    © 2026 Ryan Lyford. All rights reserved.
    Authorship attribution must be preserved in any redistribution,
    derivative work, or fork. Reports generated by this tool carry
    embedded authorship metadata.

Usage Examples:
    python3 otscope.py
    python3 otscope.py --pcap /path/to/capture.pcap
    python3 otscope.py --session /path/to/session.otpa_session
    python3 otscope.py --report-only /path/to/session.otpa_session
"""

