# ------------------------------------------------------------------
# Suspicious User-Agent / Server-banner keywords.
# Substring match (lowercased).  Maps to (severity, label, tag).
# Real OT environments should never see scanner / pentest tooling on
# the wire; legitimate OT traffic on HTTP is overwhelmingly Mozilla-
# class browsers, vendor management consoles, or curl-based health
# checks.  Aggressive bucket: tools that are unambiguous offensive
# indicators get CRITICAL; recon-class tools get HIGH.
# ------------------------------------------------------------------
