def lookup_oui_vendor(mac: str) -> str:
    """Return a short vendor label for a MAC address, or ''."""
    if not mac or len(mac) < 8:
        return ""
    prefix = mac[:8].lower()
    return OUI_VENDOR_MAP.get(prefix, "")


def passive_os_from_syn(ttl: int, window: int) -> str:
    """Classify OS family from TCP SYN TTL + window size.

    Crude but useful: SYN packets expose an initial TTL (rounded up to
    the nearest 32 or 64 boundary in practice) and an initial receive
    window that are fairly OS-specific.  Returns '' if nothing matches.
    """
    if ttl <= 0:
        return ""
    # Round TTL up to common starting values: 64, 128, 255.
    if ttl <= 64:
        initial = 64
        family = "Linux/Unix/BSD"
    elif ttl <= 128:
        initial = 128
        family = "Windows"
    elif ttl <= 255:
        initial = 255
        family = "Network device / IoT"
    else:
        return ""
    # Narrow by window size where possible.
    if initial == 64:
        if window == 5840:
            return "Linux 2.4/2.6"
        if window in (5792, 14600, 29200, 64240):
            return "Linux (modern)"
        if window == 65535:
            return "BSD / macOS"
        return family
    if initial == 128:
        if window in (8192,):
            return "Windows 7/Server 2008"
        if window in (64240, 65535):
            return "Windows 10+/Server 2016+"
        return family
    return family
