def advisories_for_finding(category: str, title: str, tags: Optional[Sequence[str]] = None) -> List[str]:
    """Look up advisory/standard references for a finding."""
    haystack = f"{category} {title}".lower()
    tag_set = {t.lower() for t in (tags or [])}
    refs: List[str] = []
    for keys, entries in ADVISORY_MAP:
        for key in keys:
            if key in haystack or key in tag_set:
                for ref in entries:
                    if ref not in refs:
                        refs.append(ref)
                break
    return refs


def mitre_for_finding(category: str, title: str, tags: Optional[Sequence[str]] = None) -> List[str]:
    """Look up MITRE ATT&CK for ICS IDs for a finding.

    Matches any substring in MITRE_ICS_MAP against "<category> <title>".
    Returns a deduplicated list of technique IDs (e.g. ['T0831','T0855']).
    """
    haystack = f"{category} {title}".lower()
    tag_set = {t.lower() for t in (tags or [])}
    ids: List[str] = []
    for keys, technique_ids in MITRE_ICS_MAP:
        for key in keys:
            if key in haystack or key in tag_set:
                for tid in technique_ids:
                    if tid not in ids:
                        ids.append(tid)
                break
    return ids


def utc_now_iso() -> str:
    """Return the current UTC timestamp in ISO-8601 format."""
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def path_exists(path_text: str) -> bool:
    """Return True if a filesystem path exists."""
    return Path(path_text).expanduser().exists()


def human_size(size_bytes: int) -> str:
    """Format a byte count as a human-readable string."""
    if size_bytes < 1024:
        return f"{size_bytes} B"
    units = ["KB", "MB", "GB", "TB"]
    value = float(size_bytes)
    for unit in units:
        value /= 1024.0
        if value < 1024.0:
            return f"{value:.1f} {unit}"
    return f"{value:.1f} PB"


def safe_slug(value: str) -> str:
    """Make a string filename-safe."""
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", value.strip())
    return cleaned.strip("_") or "session"


def colorize(text: str, severity: Optional[str] = None, bold: bool = False) -> str:
    """Apply ANSI colors when stdout is a terminal."""
    if not sys.stdout.isatty():
        return text
    color = ""
    if severity == SEVERITY_CRITICAL:
        color = ANSI_RED
    elif severity == SEVERITY_HIGH:
        color = ANSI_ORANGE
    elif severity == SEVERITY_MEDIUM:
        color = ANSI_YELLOW
    elif severity == SEVERITY_CORRELATION:
        color = ANSI_BLUE
    elif severity == SEVERITY_INTRUSION:
        color = ANSI_BRIGHT_RED
    elif severity == SEVERITY_INFO:
        color = ANSI_CYAN
    elif severity == "SUCCESS":
        color = ANSI_GREEN
    elif severity == "MUTED":
        color = ANSI_GREY
    prefix = ""
    if bold:
        prefix += ANSI_BOLD
    prefix += color
    return f"{prefix}{text}{ANSI_RESET}" if prefix else text


def print_header(title: str) -> None:
    """Print a section header."""
    print(colorize(f"\n=== {title} ===", bold=True))


def prompt_input(message: str, default: Optional[str] = None) -> str:
    """Prompt the user for input and return the stripped result."""
    suffix = f" [{default}]" if default else ""
    answer = input(f"[?] {message}{suffix}: ").strip()
    return answer or (default or "")


def prompt_yes_no(message: str, default: bool = True) -> bool:
    """Prompt for a yes/no answer."""
    default_text = "Y/n" if default else "y/N"
    answer = input(f"[?] {message} [{default_text}]: ").strip().lower()
    if not answer:
        return default
    return answer.startswith("y")


def file_sha256(path: Path) -> str:
    """Compute SHA-256 for a file."""
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def is_public_ip(ip_text: str) -> bool:
    """Return True only for routable public IPv4 addresses.

    Excludes RFC 1918, loopback, link-local, CGNAT, unspecified, multicast,
    and reserved ranges so those never trigger public-IP findings.
    """
    if not ip_text or ":" in ip_text:
        return False
    parts = ip_text.split(".")
    if len(parts) != 4:
        return False
    try:
        a, b = int(parts[0]), int(parts[1])
        c = int(parts[2])
    except ValueError:
        return False
    if a == 10:                         return False  # RFC 1918 10/8
    if a == 172 and 16 <= b <= 31:      return False  # RFC 1918 172.16/12
    if a == 192 and b == 168:           return False  # RFC 1918 192.168/16
    if a == 127:                        return False  # Loopback 127/8
    if a == 169 and b == 254:           return False  # Link-local 169.254/16
    if a == 100 and 64 <= b <= 127:     return False  # CGNAT 100.64/10
    if a == 0:                          return False  # Unspecified 0/8
    if a == 192 and b == 0 and c == 2:  return False  # TEST-NET-1 192.0.2/24
    if a == 198 and b == 51 and c == 100: return False  # TEST-NET-2 198.51.100/24
    if a == 203 and b == 0 and c == 113:  return False  # TEST-NET-3 203.0.113/24
    if a >= 224:                        return False  # Multicast + reserved
    return True


def _shannon_entropy(s: str) -> float:
    """Shannon entropy in bits of the characters in *s*."""
    if not s:
        return 0.0
    freq = Counter(s.lower())
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in freq.values())


def _dns_label_entropy(qname: str) -> Tuple[float, str]:
    """Return (entropy, label) for the most entropic non-TLD label in *qname*.

    Skips the rightmost label (the TLD) so that 'com', 'net', etc. don't
    dilute entropy scores for short domain names.
    """
    labels = qname.rstrip(".").split(".")
    candidates = labels[:-1] if len(labels) > 1 else labels
    best = max(candidates, key=lambda lb: (len(lb), _shannon_entropy(lb)))
    return _shannon_entropy(best), best


def subnet_from_ip(ip_text: str) -> str:
    """Return a /24 subnet string for IPv4 or a broader placeholder otherwise."""
    if not ip_text:
        return "unknown"
    if ":" in ip_text:
        chunks = ip_text.split(":")
        return ":".join(chunks[:4]) + "::/64"
    parts = ip_text.split(".")
    if len(parts) != 4:
        return "unknown"
    return ".".join(parts[:3]) + ".0/24"


def risk_band(score: int) -> str:
    """Map numeric risk score to a named band."""
    if score >= 120:
        return "SEVERE"
    if score >= 75:
        return "HIGH"
    if score >= 35:
        return "MODERATE"
    if score >= 10:
        return "LOW"
    return "MINIMAL"


def risk_banner(band: str) -> str:
    """Render a compact ASCII banner for the final risk band."""
    text = f" {band} RISK "
    edge = "=" * len(text)
    return f"{edge}\n{text}\n{edge}"


def pretty_json(data: Dict[str, Any]) -> str:
    """Serialize JSON in a stable, readable way."""
    return json.dumps(data, indent=2, sort_keys=True)


@dataclass
class ProcessedPcap:
    """Track a pcap already processed into a session."""

    path: str
    filename: str
    sha256: str
    size_bytes: int
    processed_at: str
    packet_count: int = 0
    start_time: Optional[str] = None
    end_time: Optional[str] = None


@dataclass
class DeviceRecord:
    """Unified device registry entry."""

    ip: str
    macs: List[str] = field(default_factory=list)
    hostnames: List[str] = field(default_factory=list)
    protocols: List[str] = field(default_factory=list)
    ports: List[int] = field(default_factory=list)
    source_pcaps: List[str] = field(default_factory=list)
    subnets: List[str] = field(default_factory=list)
    vlans: List[str] = field(default_factory=list)
    outgoing_count: int = 0
    incoming_count: int = 0
    inferred_role: str = "Unknown"
    inferred_zone: str = "Unknown"
    notes: List[str] = field(default_factory=list)
    evidence: List[str] = field(default_factory=list)
    vendors: List[str] = field(default_factory=list)
    os_fingerprint: str = ""
    user_agents: List[str] = field(default_factory=list)
    server_banners: List[str] = field(default_factory=list)


@dataclass
class ConnectionSummary:
    """Summary of a relationship between two devices."""

    source_ip: str
    destination_ip: str
    protocol: str
    destination_port: int
    packet_count: int = 0
    first_seen: Optional[str] = None
    last_seen: Optional[str] = None
    source_pcaps: List[str] = field(default_factory=list)
    notes: List[str] = field(default_factory=list)


@dataclass
class Finding:
    """Single finding in the findings registry."""

    finding_id: str
    severity: str
    category: str
    title: str
    description: str
    evidence: List[str]
    source_ips: List[str]
    destination_ips: List[str]
    protocol: str
    source_pcaps: List[str]
    next_steps: str
    created_at: str
    first_seen: Optional[str] = None
    last_seen: Optional[str] = None
    tags: List[str] = field(default_factory=list)
    score_weight: int = 0
    dedupe_key: str = ""
    mitre_ids: List[str] = field(default_factory=list)
    advisory_refs: List[str] = field(default_factory=list)


@dataclass
class SessionState:
    """Persistent session state saved to JSON."""

    name: str
    site: str
    assessor: str
    folder: str
    created_at: str
    updated_at: str
    session_file: str
    environment_answers: Dict[str, str] = field(default_factory=dict)
    processed_pcaps: Dict[str, ProcessedPcap] = field(default_factory=dict)
    devices: Dict[str, DeviceRecord] = field(default_factory=dict)
    connections: Dict[str, ConnectionSummary] = field(default_factory=dict)
    findings: List[Finding] = field(default_factory=list)
    packet_fingerprints: List[str] = field(default_factory=list)
    duplicate_packets: Dict[str, List[str]] = field(default_factory=dict)
    analysis_metadata: Dict[str, Any] = field(default_factory=dict)


def dataclass_from_dict(cls: Any, payload: Dict[str, Any]) -> Any:
    """Instantiate a dataclass from a plain dictionary.

    Ignores unknown keys so sessions saved with older versions load cleanly,
    and missing keys fall back to each field's declared default.
    """
    known = {f.name for f in cls.__dataclass_fields__.values()}  # type: ignore[attr-defined]
    return cls(**{k: v for k, v in payload.items() if k in known})


def session_to_dict(session: SessionState) -> Dict[str, Any]:
    """Serialize a session to JSON-ready dictionaries."""
    return {
        "name": session.name,
        "site": session.site,
        "assessor": session.assessor,
        "folder": session.folder,
        "created_at": session.created_at,
        "updated_at": session.updated_at,
        "session_file": session.session_file,
        "environment_answers": session.environment_answers,
        "processed_pcaps": {key: asdict(value) for key, value in session.processed_pcaps.items()},
        "devices": {key: asdict(value) for key, value in session.devices.items()},
        "connections": {key: asdict(value) for key, value in session.connections.items()},
        "findings": [asdict(finding) for finding in session.findings],
        "packet_fingerprints": session.packet_fingerprints,
        "duplicate_packets": session.duplicate_packets,
        "analysis_metadata": session.analysis_metadata,
    }


def session_from_dict(payload: Dict[str, Any]) -> SessionState:
    """Hydrate a session from a JSON dictionary."""
    session = SessionState(
        name=payload["name"],
        site=payload["site"],
        assessor=payload["assessor"],
        folder=payload["folder"],
        created_at=payload["created_at"],
        updated_at=payload["updated_at"],
        session_file=payload["session_file"],
        environment_answers=payload.get("environment_answers", {}),
        analysis_metadata=payload.get("analysis_metadata", {}),
    )
    session.processed_pcaps = {
        key: dataclass_from_dict(ProcessedPcap, value)
        for key, value in payload.get("processed_pcaps", {}).items()
    }
    session.devices = {
        key: dataclass_from_dict(DeviceRecord, value)
        for key, value in payload.get("devices", {}).items()
    }
    session.connections = {
        key: dataclass_from_dict(ConnectionSummary, value)
        for key, value in payload.get("connections", {}).items()
    }
    session.findings = [dataclass_from_dict(Finding, item) for item in payload.get("findings", [])]
    session.packet_fingerprints = payload.get("packet_fingerprints", [])
    session.duplicate_packets = payload.get("duplicate_packets", {})
    return session


def load_config() -> Dict[str, Any]:
    """Load the persisted config file."""
    if not CONFIG_PATH.exists():
        return {
            "last_pcap_folder": "",
            "last_assessor_name": "",
            "last_site_name": "",
            "write_burst_count": DEFAULT_WRITE_BURST_COUNT,
            "write_burst_seconds": DEFAULT_WRITE_BURST_SECONDS,
            "polling_anomaly_multiplier": DEFAULT_POLLING_ANOMALY_MULTIPLIER,
        }
    try:
        return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return {
            "last_pcap_folder": "",
            "last_assessor_name": "",
            "last_site_name": "",
            "write_burst_count": DEFAULT_WRITE_BURST_COUNT,
            "write_burst_seconds": DEFAULT_WRITE_BURST_SECONDS,
            "polling_anomaly_multiplier": DEFAULT_POLLING_ANOMALY_MULTIPLIER,
        }


def save_config(config: Dict[str, Any]) -> None:
    """Persist the config file."""
    CONFIG_PATH.write_text(pretty_json(config), encoding="utf-8")


def ensure_runtime_dependencies() -> None:
    """Check for required runtime tools and packages."""
    missing = []
    if shutil.which("tshark") is None:
        missing.append("tshark")
    try:
        import docx  # noqa: F401
    except ImportError:
        missing.append("python-docx")
    try:
        import scapy.all  # noqa: F401
    except ImportError:
        missing.append("scapy")
    if missing:
        print_header("Missing Dependencies")
        print("[!] The following dependencies are required before analysis can run:")
        for name in missing:
            print(f"    - {name}")
        print("\nInstall guidance:")
        print("    pip install -r requirements.txt")
        print("")
        print("    Linux / macOS alternative:")
        print("    sudo apt install tshark python3-scapy python3-docx")
        print("")
        print("    tshark must also be installed separately if missing:")
        print("      Windows: https://www.wireshark.org/download.html")
        print("      macOS:   brew install wireshark")
        raise SystemExit(1)


def next_steps_for(severity: str, category: str) -> str:
    """Generate concise remediation-oriented next-step language."""
    if "absence" in category.lower():
        return (
            "Verify capture point visibility with site staff. Consider recapturing from a different network tap point. "
            "This may indicate a segmentation issue or a system that was offline during capture."
        )
    if "boundary" in category.lower() or "segmentation" in category.lower():
        return (
            "Validate whether this communication path is intended. If not, remove the route, tighten firewall or ACL rules, "
            "and ensure OT devices can only talk to approved peers through a controlled boundary device."
        )
    if "cleartext" in category.lower() or "legacy" in category.lower():
        return (
            "Replace the legacy service with a secure alternative where possible, such as HTTPS, SSH, SNMPv3, or TLS. "
            "If the service must remain, restrict source IPs, disable unused accounts, and document the compensating controls."
        )
    if severity == SEVERITY_CRITICAL:
        return (
            "Treat this as a high-priority remediation item. Confirm whether the behavior is expected, identify the initiating host, "
            "and remove or block the risky function if it is not operationally required."
        )
    if severity == SEVERITY_INTRUSION:
        return (
            "Review the source host, timing, and target devices to determine whether this activity matches approved maintenance or testing. "
            "If not, block the path, preserve the capture, and investigate the initiating system before returning it to service."
        )
    return (
        "Confirm that the observed protocol, source, destination, and timing match intended design. "
        "If the activity is unnecessary, remove the exposure at the device, service, or firewall layer."
    )


def why_this_matters_for_finding(finding: "Finding") -> str:
    """Explain why a finding is risky in practical OT terms."""
    text = " ".join(
        [
            finding.title,
            finding.description,
            finding.category,
            finding.protocol,
            " ".join(finding.tags),
        ]
    ).lower()
    if any(term in text for term in ("write", "operate", "reset", "stop/start", "control operation", "writeproperty", "direct operate")):
        return "This finding matters because it indicates traffic that can change controller state, process values, or device configuration rather than just observe data."
    if any(term in text for term in ("cleartext", "http", "ftp", "telnet", "snmp", "basic authentication", "securitymode none", "without tls", "anonymous")):
        return "This finding matters because the protocol or session protection is weak enough that credentials, commands, or process data may be exposed or modified by anyone with network visibility."
    if any(term in text for term in ("scan", "recon", "who-is", "list identity", "browse", "identify all", "read szl", "wildcard")):
        return "This finding matters because it is consistent with discovery or enumeration activity, which is often a precursor to targeted manipulation or exploitation."
    if any(term in text for term in ("boundary", "public ip", "dual-zone", "ot-to-it", "public", "segmentation")):
        return "This finding matters because it weakens OT segmentation and increases the chance that IT-side compromise or internet exposure can directly reach control systems."
    if any(term in text for term in ("project file", "ladder", "firmware", "credential", "artifact")):
        return "This finding matters because it exposes engineering artifacts, credentials, or controller-specific metadata that can be reused for offline analysis, replay, unauthorized uploads, or follow-on access."
    if "absence" in text:
        return "This finding matters because missing expected traffic can mean the capture point had limited visibility, a device was offline, or segmentation is preventing expected communications."
    if finding.severity == SEVERITY_INTRUSION:
        return "This finding matters because it combines multiple suspicious behaviors into a pattern that is more concerning than any single packet or protocol event on its own."
    return "This finding matters because it reflects behavior that is inconsistent with a minimal, well-segmented, and tightly controlled OT network."


def recommended_fix_for_finding(finding: "Finding") -> str:
    """Provide concrete remediation guidance tailored to a finding."""
    text = " ".join(
        [
            finding.title,
            finding.description,
            finding.category,
            finding.protocol,
            " ".join(finding.tags),
        ]
    ).lower()
    if any(term in text for term in ("modbus", "bacnet", "dnp3", "cip", "s7", "opc-ua", "opcua", "mqtt")) and any(
        term in text for term in ("write", "operate", "reset", "control", "writeproperty", "direct operate")
    ):
        return "Restrict write-capable functions to approved engineering or HMI hosts only, block all other sources at the firewall or switch ACL layer, and disable unused write services where the vendor allows it."
    if any(term in text for term in ("securitymode none", "without tls", "cleartext", "http", "ftp", "telnet", "basic authentication", "anonymous")):
        return "Enable the strongest supported authentication and encryption for the protocol, disable insecure legacy access methods, rotate any exposed credentials, and limit access to a dedicated management subnet."
    if any(term in text for term in ("public ip", "ot-to-it", "dual-zone", "boundary", "segmentation")):
        return "Remove direct routing where possible, place a firewall or industrial DMZ between the zones, permit only explicitly required ports, and force administration through an approved jump host."
    if any(term in text for term in ("scan", "recon", "who-is", "list identity", "identify all", "browse", "read szl", "wildcard")):
        return "Identify the scanning source, confirm whether it is an approved management station, and if not, block its access to OT ports, disable unnecessary discovery services, and alert operations that device enumeration occurred."
    if any(term in text for term in ("project file", "ladder", "firmware")):
        return "Limit file-transfer paths between corporate, engineering, and control assets; disable unnecessary FTP, TFTP, SMB, or web download functions on PLC-facing systems; and require authenticated engineering workstations for any program transfer."
    if any(term in text for term in ("credential", "password", "web user")):
        return "Rotate the exposed credentials, remove any default or shared administrative passwords, enforce unique role-based accounts, and disable any management interface that exposes authentication material in cleartext."
    if "absence" in text:
        return "Retake the capture from a better vantage point, confirm the device was online during collection, and compare expected protocol flows against firewall rules and switch topology."
    if "dns" in text:
        return "Point OT assets only to approved internal DNS services if name resolution is required, or remove DNS access entirely from controllers that should operate by IP only."
    if "ntp" in text:
        return "Use a local internal time source for OT assets and block direct queries to public time servers from the control network."
    if finding.severity in {SEVERITY_CRITICAL, SEVERITY_INTRUSION}:
        return "Start with the initiating host and target devices, verify the behavior against change records, then block, disable, or reconfigure the exposed path so the same action cannot be repeated from an unauthorized source."
    return finding.next_steps


